INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DDL nur dazu da, Daten zu löschen?', 2, '[{"text": "Nein", "correct": true, "because": "DDL definiert Strukturen wie Tabellen"}, {"text": "Ja", "correct": false, "because": "Löschen ist DML"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl nutze ich, um eine Tabelle zu erstellen?', 3, '[{"text": "CREATE TABLE", "correct": true, "because": "Erstellt Tabellenstruktur"}, {"text": "INSERT INTO", "correct": false, "because": "Fügt Daten ein"}, {"text": "SELECT", "correct": false, "because": "Fragt Daten ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt DDL in einer Datenbank?', 5, '[{"text": "Tabellen definieren", "correct": true, "because": "Struktur festlegen"}, {"text": "Indizes erstellen", "correct": true, "because": "Optimierung gehört dazu"}, {"text": "Daten einfügen", "correct": false, "because": "Das ist DML"}, {"text": "Daten abfragen", "correct": false, "because": "Das ist DQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DDL ändert Tabellenstrukturen. b) DDL fragt Daten ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen sind DQL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Datenbankstruktur plane?', 4, '[{"text": "Datentypen", "correct": false, "because": "Essenziell für Definition"}, {"text": "Primärschlüssel", "correct": false, "because": "Wichtig für Identifikation"}, {"text": "Benutzeroberfläche", "correct": true, "because": "Nicht Teil der Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DROP TABLE Daten sichert?', 2, '[{"text": "Nein", "correct": true, "because": "Löscht Tabelle komplett"}, {"text": "Ja", "correct": false, "because": "Keine Sicherungsfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um eine Spalte hinzuzufügen?', 3, '[{"text": "ALTER TABLE", "correct": true, "because": "Ändert Struktur"}, {"text": "UPDATE", "correct": false, "because": "Ändert Daten"}, {"text": "DELETE", "correct": false, "because": "Löscht Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente definiere ich mit DDL?', 5, '[{"text": "Tabellen", "correct": true, "because": "Grundstruktur"}, {"text": "Constraints", "correct": true, "because": "Regeln wie PK/FK"}, {"text": "Datenwerte", "correct": false, "because": "Das ist DML"}, {"text": "Abfragen", "correct": false, "because": "Das ist DQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DDL ist für Struktur. b) DDL fügt Daten ein. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daten sind DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich eine Tabelle erstelle?', 4, '[{"text": "Spaltennamen", "correct": false, "because": "Teil der Definition"}, {"text": "Datentypen", "correct": false, "because": "Pflichtangabe"}, {"text": "Datenwerte", "correct": true, "because": "Erst bei INSERT nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DDL auch für Datenmanipulation?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Struktur, nicht Daten"}, {"text": "Ja", "correct": false, "because": "DML ist dafür zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ich mit DDL ändern?', 4, '[{"text": "Tabellenstruktur", "correct": true, "because": "ALTER TABLE"}, {"text": "Spaltentypen", "correct": true, "because": "Modifikation möglich"}, {"text": "Datenwerte", "correct": false, "because": "DML-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DDL auch Daten löscht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "DROP löscht Struktur und Daten"}, {"text": "Nein", "correct": false, "because": "DROP ist DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Strukturdefinition?', 3, '[{"text": "Klarheit der Regeln", "correct": true, "because": "Constraints wie PK wichtig"}, {"text": "Schnelle Abfragen", "correct": false, "because": "DQL-Optimierung"}, {"text": "Datenmenge", "correct": false, "because": "DML-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DDL erstellt Indizes. b) DDL manipuliert Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daten sind DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt DDL?', 5, '[{"text": "Strukturierte Daten", "correct": true, "because": "Tabellen klar definiert"}, {"text": "Konsistenz", "correct": true, "because": "Constraints sichern"}, {"text": "Datenänderung", "correct": false, "because": "DML-Bereich"}, {"text": "Schnelle Abfragen", "correct": false, "because": "DQL-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Struktur unwichtig?', 3, '[{"text": "Datentypen", "correct": false, "because": "Kern der Definition"}, {"text": "Constraints", "correct": false, "because": "Sichern Integrität"}, {"text": "Farbschema", "correct": true, "because": "Kein Datenbankthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich mit DDL Daten abfragen?', 3, '[{"text": "Nein", "correct": true, "because": "Abfragen sind DQL"}, {"text": "Ja", "correct": false, "because": "DDL ist für Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DDL Transaktionen unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "DDL kann in Transaktionen laufen"}, {"text": "Nein", "correct": false, "because": "Abhängig vom System möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl nutze ich, um eine Tabelle zu löschen?', 4, '[{"text": "DROP TABLE", "correct": true, "because": "Entfernt Struktur"}, {"text": "DELETE", "correct": false, "because": "Nur Daten"}, {"text": "TRUNCATE", "correct": false, "because": "Daten ohne Struktur"}]');
